  <script src="https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/expr-eval@2/dist/bundle.min.js"></script>

  <style>
    /* ── Reset ───────────────────────────────────────────────────────────── */
    html,
    body {
      margin: 0;
      padding: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #fff;
    }

    /* ── Layout ──────────────────────────────────────────────────────────────
       body is a grid so #ui always takes a right-side column instead of covering
       the figure. The #container ResizeObserver then fires 'fig-resize', so
       setPlotFrame re-lays the figure out at its new size automatically.        */
    body {
      display: grid;
      grid-template-columns: 1fr;
      grid-template-rows: 1fr;
      grid-template-areas: "stage";
    }

    /* ── Figure mount point ──────────────────────────────────────────────── */
    #container {
      position: relative;
      grid-area: stage;
      min-width: 0;
      min-height: 0;
      overflow: hidden;
      box-sizing: border-box;
      padding: var(--figure-canvas-padding, 18px);
    }

    /* ── Control panel (mirrors base_scene_new.html #ui) ─────────────────── */
    #ui {
      position: absolute;
      left: 6px;
      bottom: 6px;
      display: flex;
      flex-direction: column;
      gap: 3px;
      font-family: sans-serif;
      font-size: 11px;
      max-width: 190px;
      max-height: 34%;
      overflow-y: auto;
      overflow-x: hidden;
      background: transparent;
      border: 0;
      box-shadow: none;
      opacity: 0.88;
      transform: none;
      transition: opacity 0.16s ease;
      z-index: 10;
    }

    #ui:hover,
    #ui:focus-within {
      opacity: 1;
    }

    #ui button {
      padding: 4px 10px;
      cursor: pointer;
      border: 1px solid #aaa;
      background: #f5f5f5;
      border-radius: 4px;
    }

    #ui button:hover {
      background: #e0e0e0;
    }

    #ui button.active {
      background: #c8e6ff;
      border-color: #5aabf0;
    }

    #ui label {
      display: flex;
      flex-direction: column;
      gap: 2px;
      text-shadow: 0 1px 2px #fff;
    }

    #ui input[type=range] {
      width: 86px;
    }

    /* ── Docked control panel ────────────────────────────────────────────────
       #ui is a grid cell with its own scroll, an opaque background, and roomier
       type. Generated code cannot switch it to an overlay or bottom strip.      */
    body[data-ui-layout="right"] {
      grid-template-columns: 1fr var(--ui-size, 320px);
      grid-template-rows: 1fr;
      grid-template-areas: "stage ui";
    }

    body[data-ui-layout="bottom"] {
      grid-template-columns: 1fr;
      grid-template-rows: 1fr var(--ui-size, 240px);
      grid-template-areas: "stage" "ui";
    }

    body[data-ui-layout="right"] #ui,
    body[data-ui-layout="bottom"] #ui {
      position: relative;
      grid-area: ui;
      left: auto;
      bottom: auto;
      max-width: none;
      max-height: none;
      min-width: 0;
      min-height: 0;
      width: auto;
      height: auto;
      gap: 6px;
      padding: 10px 12px;
      font-size: 12px;
      background: #fbfbfc;
      opacity: 1;
      overflow: auto;
      z-index: 1;
    }

    body[data-ui-layout="right"] #ui {
      border-left: 1px solid #dcdfe3;
    }

    body[data-ui-layout="bottom"] #ui {
      border-top: 1px solid #dcdfe3;
    }

    body[data-ui-layout="right"] #ui label,
    body[data-ui-layout="bottom"] #ui label {
      text-shadow: none;
    }

    body[data-ui-layout="right"] #ui input[type=range],
    body[data-ui-layout="bottom"] #ui input[type=range] {
      width: 100%;
    }

    body[data-ui-layout="right"] #ui textarea,
    body[data-ui-layout="bottom"] #ui textarea {
      width: 100%;
      box-sizing: border-box;
      min-height: 180px;
      resize: vertical;
      font-family: ui-monospace, Consolas, monospace;
      font-size: 11px;
      line-height: 1.45;
      tab-size: 2;
      border: 1px solid #cfd4da;
      border-radius: 4px;
      padding: 6px 8px;
    }

    body[data-ui-layout="bottom"] #ui textarea {
      min-height: 110px;
    }

    /* ── Inline equation parse errors ────────────────────────────────────── */
    .eq-err {
      color: #c00000;
      font-size: 10px;
      max-width: 180px;
      white-space: normal;
      text-shadow: 0 1px 2px #fff;
    }

    /* ── Hover tooltip ───────────────────────────────────────────────────── */
    #figTooltip {
      position: fixed;
      left: 0;
      top: 0;
      display: none;
      max-width: 210px;
      padding: 4px 8px;
      border-radius: 4px;
      background: rgba(0, 0, 0, 0.58);
      color: #fff;
      font: 11px/1.35 sans-serif;
      pointer-events: none;
      white-space: normal;
      z-index: 20;
    }
  </style>
</head>

<body data-ui-layout="right">
  <div id="container"></div>
  <div id="figTooltip"></div>
  <div id="ui">
    <!-- @FIGURE_UI_BEGIN -->
    <!-- @FIGURE_UI_END -->
  </div>

  <!-- Error overlay: shown if CDN fails or JS throws before rendering -->
  <div id="err-overlay" style="display:none;position:fixed;inset:0;background:#fff;z-index:999;
       flex-direction:column;align-items:center;justify-content:center;
       font-family:sans-serif;font-size:13px;color:#555;gap:10px;">
    <span id="err-msg">⚠ Figure failed to load</span>
    <button onclick="location.reload()" style="padding:5px 14px;border:1px solid #aaa;
        border-radius:5px;background:#f5f5f5;cursor:pointer;font-size:12px;">↻ Reload</button>
  </div>

  <script>
    /* ── Error overlay ───────────────────────────────────────────────────── */
    var _rendered = false;
    var _errOverlay = document.getElementById('err-overlay');
    window.__markRendered = function () { _rendered = true; _errOverlay.style.display = 'none'; };
    window.addEventListener('error', function (e) {
      if (!_rendered) {
        document.getElementById('err-msg').textContent = '⚠ ' + (e.message || 'Figure failed to load');
        _errOverlay.style.display = 'flex';
      }
    });
    setTimeout(function () { if (!_rendered) { _errOverlay.style.display = 'flex'; } }, 12000);

    /* ── Tooltip + popup helpers ─────────────────────────────────────────── */
    var _tooltip = document.getElementById('figTooltip');

    function showPopup(title, body) {
      window.parent.postMessage({ type: 'alex-popup', title: title, body: body }, '*');
    }
    function hidePopup() {
      window.parent.postMessage({ type: 'alex-popup', title: null }, '*');
    }
    function showTooltip(text, event) {
      if (!_tooltip || !text) return;
      _tooltip.textContent = text;
      _tooltip.style.display = 'block';
      _moveTooltip(event);
    }
    function _moveTooltip(event) {
      if (!_tooltip || _tooltip.style.display === 'none') return;
      var pad = 12;
      var x = Math.min(event.clientX + pad, window.innerWidth - (_tooltip.offsetWidth || 100) - pad);
      var y = Math.max(pad, event.clientY - (_tooltip.offsetHeight || 40) - pad);
      _tooltip.style.left = x + 'px';
      _tooltip.style.top = y + 'px';
    }
    function hideTooltip() {
      if (_tooltip) _tooltip.style.display = 'none';
    }
    document.addEventListener('mousemove', function (e) { _moveTooltip(e); });

    /* ── Resize event ────────────────────────────────────────────────────── */
    function _containerInnerSize() {
      var container = document.getElementById('container');
      var style = getComputedStyle(container);
      var padX = (parseFloat(style.paddingLeft) || 0) + (parseFloat(style.paddingRight) || 0);
      var padY = (parseFloat(style.paddingTop) || 0) + (parseFloat(style.paddingBottom) || 0);
      return {
        width: Math.max(0, container.clientWidth - padX),
        height: Math.max(0, container.clientHeight - padY)
      };
    }

    new ResizeObserver(function () {
      var rect = _containerInnerSize();
      document.dispatchEvent(new CustomEvent('fig-resize', {
        detail: { width: rect.width, height: rect.height }
      }));
    }).observe(document.getElementById('container'));

    /* ── UI layout: keep controls in a right-side column ─────────────────────
     * setUiLayout(...) is retained only so older generated payloads do not
     * crash. It deliberately cannot change the side, overlay state, or size.
     * Docking resizes #container, which fires 'fig-resize', so setPlotFrame
     * re-lays the figure out at its new size instead of it being covered.
     */
    var _uiEl = document.getElementById('ui');

    function setUiLayout(mode, sizePx) {
      _autoUiLayout();
    }

    function _applyUiLayout(mode, sizePx) {
      var next = 'right';
      document.body.setAttribute('data-ui-layout', next);
      if (sizePx) document.body.style.setProperty('--ui-size', sizePx + 'px');
    }

    // Generated figures do not get to decide panel placement: a stable right
    // column prevents controls from covering the figure and avoids layout jumps.
    var _autoUiTimer = 0;
    function _autoUiLayout() {
      var hasEditor = Boolean(_uiEl.querySelector('textarea'));
      var mode = 'right';
      var start = hasEditor ? 400 : 300;
      _applyUiLayout(mode, start);
      _growDockToFit(mode, start);
    }

    // A fixed dock size still clips a long control stack in a small inline
    // figure. Grow the dock until the panel stops scrolling, capped so the
    // figure always keeps the larger share of the frame.
    function _growDockToFit(mode, startPx) {
      var cap = Math.round(window.innerWidth * 0.45);
      // Clamp down too: on a small figure the default dock can itself exceed the
      // cap, and the figure must always keep the larger share.
      var size = Math.min(startPx, cap);
      if (size !== startPx) document.body.style.setProperty('--ui-size', size + 'px');
      var guard = 0;
      function step() {
        if (guard++ > 6) return;
        if (_uiEl.scrollHeight <= _uiEl.clientHeight + 2 || size >= cap) return;
        size = Math.min(cap, size + 60);
        document.body.style.setProperty('--ui-size', size + 'px');
        requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }
    window.__autoUiLayout = _autoUiLayout;

    // Re-evaluate when generated code adds controls after first paint.
    new MutationObserver(function () {
      clearTimeout(_autoUiTimer);
      _autoUiTimer = setTimeout(_autoUiLayout, 0);
    }).observe(_uiEl, { childList: true, subtree: true });
    window.addEventListener('resize', function () { _autoUiLayout(); });

    /* ── Keyboard dismiss ────────────────────────────────────────────────── */
    window.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { hidePopup(); hideTooltip(); }
    });

    /* ── Expression parsing ──────────────────────────────────────────────── */
    /**
     * compileExpr(src, vars) → function(...args)
     *   src  : math source, e.g. 'sin(x) + 1', 'x^2', '2*x - 3'
     *   vars : variable names in argument order, e.g. ['x'] or ['x', 'y']
     * Throws an Error with a readable message on a syntax error or when the
     * source references a variable outside `vars`. Never returns a fallback.
     *
     * DUPLICATED (deliberately): base_scene_new.html has an equivalent ES-module
     * copy. Each scaffold is a standalone served HTML file and neither can
     * import the other, so behaviour changes must be made TWICE.
     * Keep this in sync with compileExpr in base_scene_new.html.
     */
    function compileExpr(src, vars) {
      if (!window.exprEval || !window.exprEval.Parser) {
        throw new Error('Expression parser unavailable (expr-eval CDN did not load)');
      }
      var names = (vars && vars.length) ? vars : ['x'];
      var parsed;
      try {
        parsed = new window.exprEval.Parser().parse(String(src));
      } catch (e) {
        throw new Error('Cannot parse "' + src + '": ' + ((e && e.message) ? e.message : e));
      }
      var used = parsed.variables();
      for (var i = 0; i < used.length; i++) {
        if (names.indexOf(used[i]) === -1) {
          throw new Error('Unknown variable "' + used[i] + '" (expected: ' + names.join(', ') + ')');
        }
      }
      return function () {
        var scope = {};
        for (var j = 0; j < names.length; j++) scope[names[j]] = arguments[j];
        var v;
        try { v = parsed.evaluate(scope); } catch (e) { return NaN; }
        return (typeof v === 'number') ? v : NaN;
      };
    }

    /* ── Plot frame: world → screen mapping (owns resize) ────────────────── */
    var _plotFrame = null;
    var _plots = [];
    var _plotResizeBound = false;

    /**
     * setPlotFrame({ xDomain, yDomain, margin, draw }) → frame
     * Establishes the world→screen mapping used by plotX / plotY and by every
     * plot helper. Call this once, before creating any plots. Registered plots
     * are re-sampled automatically on resize.
     */
    function setPlotFrame(opts) {
      opts = opts || {};
      var innerSize = _containerInnerSize();
      _plotFrame = {
        xDomain: opts.xDomain || [-5, 5],
        yDomain: opts.yDomain || [-5, 5],
        margin: (opts.margin == null) ? 24 : opts.margin,
        draw: opts.draw || SVG().addTo('#container').size('100%', '100%'),
        width: innerSize.width || 900,
        height: innerSize.height || 600
      };
      _recomputePlotScale();
      if (!_plotResizeBound) {
        _plotResizeBound = true;
        document.addEventListener('fig-resize', function (e) {
          if (!_plotFrame) return;
          _plotFrame.width = e.detail.width || _plotFrame.width;
          _plotFrame.height = e.detail.height || _plotFrame.height;
          _recomputePlotScale();
          for (var i = 0; i < _plots.length; i++) _plots[i].sample();
        });
      }
      return _plotFrame;
    }

    function _recomputePlotScale() {
      var f = _plotFrame, m = f.margin;
      f.sx = (f.width - 2 * m) / (f.xDomain[1] - f.xDomain[0]);
      f.sy = (f.height - 2 * m) / (f.yDomain[1] - f.yDomain[0]);
    }

    /** plotX(worldX) → screen px. Requires setPlotFrame() first. */
    function plotX(wx) {
      var f = _plotFrame;
      return f.margin + (wx - f.xDomain[0]) * f.sx;
    }

    /** plotY(worldY) → screen px (y axis flipped). Requires setPlotFrame() first. */
    function plotY(wy) {
      var f = _plotFrame;
      return f.height - f.margin - (wy - f.yDomain[0]) * f.sy;
    }

    function _registerPlot(handle) {
      _plots.push(handle);
      return handle;
    }

    function _unregisterPlot(handle) {
      var i = _plots.indexOf(handle);
      if (i >= 0) _plots.splice(i, 1);
    }

    function _resolveFn(value, vars) {
      if (typeof value === 'function') return value;
      return compileExpr(value, vars);
    }

    function _pointsAttr(points) {
      return points.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
    }

    /**
     * plotFunction(id, opts) → handle
     *   opts: { expr | fn, variables=['x'], domain, samples=200,
     *           stroke='#1f77b4', width=2, dashed=false }
     * The drawn polyline is ALWAYS produced by sampling the compiled function
     * across `domain`. Non-finite samples split the line into segments instead
     * of drawing a spike.
     */
    function plotFunction(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['x'];
      var group = _plotFrame.draw.group().attr('id', 'plot-' + id);
      var handle = {
        id: id,
        node: group,
        fn: opts.fn ? opts.fn : (opts.expr != null ? compileExpr(opts.expr, vars) : null),
        domain: opts.domain || _plotFrame.xDomain.slice(),
        samples: opts.samples || 200,
        setExpr: function (src) { this.fn = _resolveFn(src, vars); return this.sample(); },
        setFn: function (f) { this.fn = f; return this.sample(); },
        setDomain: function (dm) { this.domain = dm; return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          if (!this.fn) return this;
          var segs = _sampleSegments(this.fn, this.domain, this.samples);
          for (var s = 0; s < segs.length; s++) {
            if (segs[s].length < 2) continue;
            var line = group.polyline(_pointsAttr(segs[s]))
              .fill('none')
              .stroke({
                color: opts.stroke || '#1f77b4',
                width: opts.width || 2,
                linecap: 'round',
                linejoin: 'round'
              });
            if (opts.dashed) line.attr('stroke-dasharray', '5,4');
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /** Sample fn across domain, splitting at non-finite values. → [[ [px,py], … ], …] */
    function _sampleSegments(fn, domain, samples) {
      var a = domain[0], b = domain[1], n = Math.max(2, samples | 0);
      var segs = [], cur = [];
      for (var i = 0; i < n; i++) {
        var t = a + (b - a) * (i / (n - 1));
        var v;
        try { v = fn(t); } catch (e) { v = NaN; }
        if (typeof v === 'number' && isFinite(v)) {
          cur.push([plotX(t), plotY(v)]);
        } else if (cur.length) {
          segs.push(cur);
          cur = [];
        }
      }
      if (cur.length) segs.push(cur);
      return segs;
    }

    /**
     * fillBetween(id, opts) → handle
     *   opts: { lower, upper, variables=['x'], domain, samples=200,
     *           fill='#7fb3ff', opacity=0.45, stroke, strokeWidth=1 }
     * `lower` / `upper` may be expression strings or functions. The polygon is
     * built from EVERY sampled point on both boundaries, so a curved boundary
     * produces a curved region with no caller involvement.
     */
    function fillBetween(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['x'];
      var group = _plotFrame.draw.group().attr('id', 'fill-' + id);
      var handle = {
        id: id,
        node: group,
        lower: opts.lower != null ? _resolveFn(opts.lower, vars) : function () { return 0; },
        upper: opts.upper != null ? _resolveFn(opts.upper, vars) : function () { return 0; },
        domain: opts.domain || _plotFrame.xDomain.slice(),
        samples: opts.samples || 200,
        setLower: function (src) { this.lower = _resolveFn(src, vars); return this.sample(); },
        setUpper: function (src) { this.upper = _resolveFn(src, vars); return this.sample(); },
        setDomain: function (dm) { this.domain = dm; return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          var a = this.domain[0], b = this.domain[1], n = Math.max(2, this.samples | 0);
          var top = [], bottom = [];
          for (var i = 0; i < n; i++) {
            var t = a + (b - a) * (i / (n - 1));
            var lo, hi;
            try { lo = this.lower(t); hi = this.upper(t); } catch (e) { lo = NaN; hi = NaN; }
            if (isFinite(lo) && isFinite(hi)) {
              top.push([plotX(t), plotY(hi)]);
              bottom.push([plotX(t), plotY(lo)]);
            }
          }
          if (top.length < 2) return this;
          bottom.reverse();
          var poly = group.polygon(_pointsAttr(top.concat(bottom)))
            .fill({
              color: opts.fill || '#7fb3ff',
              opacity: (opts.opacity == null) ? 0.45 : opts.opacity
            });
          if (opts.stroke) {
            poly.stroke({ color: opts.stroke, width: opts.strokeWidth || 1, linejoin: 'round' });
          } else {
            poly.stroke('none');
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /**
     * plotParametric(id, opts) → handle
     *   opts: { x, y, variables=['t'], tDomain=[0,1], samples=200, stroke, width }
     */
    function plotParametric(id, opts) {
      opts = opts || {};
      var vars = opts.variables || ['t'];
      var group = _plotFrame.draw.group().attr('id', 'param-' + id);
      var handle = {
        id: id,
        node: group,
        fx: _resolveFn(opts.x, vars),
        fy: _resolveFn(opts.y, vars),
        tDomain: opts.tDomain || [0, 1],
        samples: opts.samples || 200,
        setX: function (src) { this.fx = _resolveFn(src, vars); return this.sample(); },
        setY: function (src) { this.fy = _resolveFn(src, vars); return this.sample(); },
        remove: function () { group.remove(); _unregisterPlot(this); },
        sample: function () {
          group.clear();
          var a = this.tDomain[0], b = this.tDomain[1], n = Math.max(2, this.samples | 0);
          var pts = [];
          for (var i = 0; i < n; i++) {
            var t = a + (b - a) * (i / (n - 1));
            var vx, vy;
            try { vx = this.fx(t); vy = this.fy(t); } catch (e) { vx = NaN; vy = NaN; }
            if (isFinite(vx) && isFinite(vy)) pts.push([plotX(vx), plotY(vy)]);
          }
          if (pts.length >= 2) {
            group.polyline(_pointsAttr(pts))
              .fill('none')
              .stroke({
                color: opts.stroke || '#1f77b4', width: opts.width || 2,
                linecap: 'round', linejoin: 'round'
              });
          }
          return this;
        }
      };
      return _registerPlot(handle).sample();
    }

    /** integrateSimpson(fn, a, b, n=200) → number. Composite Simpson's rule. */
    function integrateSimpson(fn, a, b, n) {
      n = Math.max(2, n || 200);
      if (n % 2) n++;
      var h = (b - a) / n, s = fn(a) + fn(b);
      for (var i = 1; i < n; i++) s += fn(a + i * h) * ((i % 2) ? 4 : 2);
      return (s * h) / 3;
    }

    /** findRoot(fn, a, b, tol=1e-9) → number | null. Bisection; null if no sign change. */
    function findRoot(fn, a, b, tol) {
      tol = tol || 1e-9;
      var fa = fn(a), fb = fn(b);
      if (!isFinite(fa) || !isFinite(fb) || fa * fb > 0) return null;
      for (var i = 0; i < 200; i++) {
        var m = (a + b) / 2, fm = fn(m);
        if (!isFinite(fm)) return null;
        if (Math.abs(fm) < tol || (b - a) / 2 < tol) return m;
        if (fa * fm < 0) { b = m; } else { a = m; fa = fm; }
      }
      return (a + b) / 2;
    }

    /* ── Equation input binding ──────────────────────────────────────────── */
    /**
     * The error slot is keyed PER INPUT (id "eq-err-<inputId>"), never just
     * "the first .eq-err under my parent": generated figures routinely put
     * several equation inputs under one parent, and a shared slot means a valid
     * edit of field B hides field A's still-current parse error, leaving A's
     * curve stale with nothing on screen to explain why.
     * The .eq-err class is kept so the scaffold CSS still applies.
     *
     * DUPLICATED: keep in sync with _equationErrorSlot in base_scene_new.html.
     */
    function _equationErrorSlot(input) {
      var parent = input.parentNode || document.getElementById('ui');
      if (input.id) {
        var slotId = 'eq-err-' + input.id;
        var byId = document.getElementById(slotId);
        if (byId) return byId;
        var namedSpan = document.createElement('span');
        namedSpan.id = slotId;
        namedSpan.className = 'eq-err';
        namedSpan.style.display = 'none';
        parent.appendChild(namedSpan);
        return namedSpan;
      }
      var existing = parent.querySelector('.eq-err');
      if (existing) return existing;
      var span = document.createElement('span');
      span.className = 'eq-err';
      span.style.display = 'none';
      parent.appendChild(span);
      return span;
    }

    /**
     * _resolveEqTarget(inputId, t) → function(fn, src)
     * Turns one bindEquationInput target into a concrete applier, and THROWS on
     * anything it cannot drive. Silently skipping an unrecognised target is the
     * worst possible outcome: the figure renders, typing changes nothing, and
     * nothing reports it. Throwing makes verify2dHtml catch the mistake at
     * generation time instead of the student discovering it.
     *
     * DUPLICATED: keep in sync with _resolveEqTarget in base_scene_new.html.
     */
    function _resolveEqTarget(inputId, t) {
      if (typeof t === 'function') {
        return function (fn, src) { t(fn, src); };
      }
      if (t && t.handle) {
        var method = t.method || 'setFn';
        if (typeof t.handle[method] !== 'function') {
          throw new Error(
            'bindEquationInput("' + inputId + '"): target handle has no method "' + method +
            '". Use { handle, method: \'...\' } with a method the handle really has ' +
            '(plotFunction: setExpr, setFn; fillBetween: setLower, setUpper; ' +
            'plotParametric: setX, setY).'
          );
        }
        return function (fn) { t.handle[method](fn); };
      }
      if (t && typeof t.setFn === 'function') {
        return function (fn) { t.setFn(fn); };
      }
      throw new Error(
        'bindEquationInput("' + inputId + '"): this target cannot be driven — it is not a ' +
        'function and has no .setFn. Handles without .setFn (fillBetween, plotParametric) ' +
        'must be passed as { handle, method: \'setUpper\' } naming the setter to call.'
      );
    }

    /**
     * bindEquationInput(inputId, targets, opts) → { apply, input, errorSlot }
     *   targets: a plot handle, a { handle, method } pair, a function(fn, src),
     *            or an array of any of those.
     *   opts   : { variables=['x'], onChange(fn, src) }
     *
     * On every valid edit, every target re-samples. On a parse error the last
     * good curve is kept and the message is shown inline — this function NEVER
     * substitutes a hardcoded default.
     * Throws at bind time on a target it cannot drive (see _resolveEqTarget).
     *
     * DUPLICATED: keep in sync with bindEquationInput in base_scene_new.html.
     */
    function bindEquationInput(inputId, targets, opts) {
      opts = opts || {};
      var input = document.getElementById(inputId);
      if (!input) throw new Error('bindEquationInput: no element with id "' + inputId + '"');
      var vars = opts.variables || ['x'];
      var list = Array.isArray(targets) ? targets : [targets];
      var slot = _equationErrorSlot(input);
      // Validated once, loudly, before anything is wired up.
      var appliers = [];
      for (var k = 0; k < list.length; k++) appliers.push(_resolveEqTarget(inputId, list[k]));

      function apply(src) {
        try {
          // The dispatch is INSIDE the try as well: an error thrown while
          // applying (a target callback that throws, a handle mutated later)
          // would otherwise escape uncaught from the input event handler and
          // leave the figure stale with no visible reason.
          var fn = compileExpr(src, vars);
          for (var i = 0; i < appliers.length; i++) appliers[i](fn, src);
          if (typeof opts.onChange === 'function') opts.onChange(fn, src);
        } catch (e) {
          slot.textContent = e.message;
          slot.style.display = '';
          input.setAttribute('data-eq-valid', 'false');
          return false;
        }
        slot.textContent = '';
        slot.style.display = 'none';
        input.setAttribute('data-eq-valid', 'true');
        return true;
      }

      input.addEventListener('input', function () { apply(input.value); });
      apply(input.value);
      return { apply: apply, input: input, errorSlot: slot };
    }

    // @FIGURE_CODE_BEGIN
    // @FIGURE_CODE_END

    // Decide the panel layout once the generated UI exists. Runs last so it sees
    // the final #ui content; a setUiLayout() call in the block above wins.
    _autoUiLayout();
  </script>
</body>

</html>

GLOBALS (do not re-declare): showPopup(title,body), showTooltip(text,event), hideTooltip(), #container (mount target), window.__markRendered() (call once when drawn), 'fig-resize' CustomEvent on document, setUiLayout(mode, sizePx).
  #ui is always docked as a right-side column by the scaffold and grows to fit its content. setUiLayout(...) exists only for backwards compatibility and cannot change the side, overlay state, or size. Just put controls in #ui. Never restyle #ui's position/width/max-height and never build your own side panel. Docking resizes #container and fires 'fig-resize', so setPlotFrame re-lays the figure out at its new size.

LIBRARY: SVG.js v3 (global: SVG). var draw=SVG().addTo(document.getElementById('container')).size('100%','100%'); var W=600,H=Math.round(W*(3/4)); draw.viewbox(0,0,W,H). font-size in user units (no px). Hover: el.on('mousemove',e=>showTooltip('label',e)).on('mouseleave',()=>hideTooltip()).on('click',()=>showPopup('Title','body')); el.css('cursor','pointer'). window.__markRendered() synchronously at end.
PLOTTING HELPERS (do not re-declare, and do NOT define your own X()/Y() — use plotX/plotY):
  setPlotFrame({ xDomain, yDomain, margin }) → call ONCE before creating plots; establishes world→screen and owns resize (do not write your own plot resize handler)
  plotX(worldX) / plotY(worldY) → screen px
  compileExpr(src, vars) → f(...args); throws on a bad expression and never returns a fallback
  bindEquationInput(inputId, targets, { variables, onChange }) → wires an <input> to plot handles and shows parse errors inline
  plotFunction(id, { expr, variables, domain, samples, stroke, width, dashed }) → handle
  fillBetween(id, { lower, upper, variables, domain, samples, fill, opacity }) → handle
  plotParametric(id, { x, y, variables, tDomain, samples, stroke }) → handle
  variables: the argument names the expression may use, in order (defaults: plotFunction ['x'], fillBetween ['x'], plotParametric ['t']). When a blueprint field declares "variables" you MUST pass that same array to BOTH the plot constructor and bindEquationInput — plotFunction('f', { expr: 't^2' }) without { variables: ['t'] } throws "Unknown variable t" at construction and kills the whole figure.
  integrateSimpson(fn, a, b, n) → number;  findRoot(fn, a, b, tol) → number | null
  Handles re-sample on EVERY setter call, and the setters differ: plotFunction → .setExpr / .setFn / .setDomain · fillBetween → .setLower / .setUpper / .setDomain · plotParametric → .setX / .setY. All handles also have .sample() and .remove().

VISUAL FIDELITY: the default state must be a faithful inline replacement for the source image.
- Color scheme: match every color exactly — axis lines, data series, fills, backgrounds
- Layout & proportions: same relative element positions, same axis ranges, same tick marks and gridlines
- Data shape: match curve trajectories, bar heights, scatter clusters, or node/edge layout — approximate magnitudes, not invented
- Labels & annotations: every label visible in the original must appear at the same position; use blueprint.reconstructionNotes for text and color coding
- Line styles: dashed vs solid, stroke weights, arrowhead presence — copy from the image
- The step-0 (default) state should look indistinguishable from the original at a glance, with no title bar or toolbar visible

TEXT PLACEMENT & READABILITY: faithful labels must still be readable.
- Treat every label, tick label, annotation, formula, and legend item as a collision-checked box, and check each one against lines, arrows, curves, points, nodes, tick marks, gridlines, controls, and other text before finalizing. Text must not sit on top of strokes or dense marks.
- If the source label is anchored to a busy line/arrow/node, keep the semantic anchor but move the text to the nearest open whitespace and connect it with a short leader line, pointer, or subtle dot.
- Draw text and label backgrounds after geometry so labels are on top. Over busy regions add a small white/translucent background rect, or a halo: text.attr({ 'paint-order':'stroke', stroke:'#fff', 'stroke-width':3, 'stroke-linejoin':'round' }).
- Do not add extra visible explanatory text inside the figure; use hover tooltips, click popups, and the scaffold narration panel for explanation.

SCALE SAFETY: figures may be stitched into chapters at different sizes.
- With Canvas, Chart.js custom drawing, or any pixel-based renderer, derive point radius, stroke width, arrowheads, ticks, label size, and annotation padding from min(plotWidth, plotHeight). Avoid large fixed pixel minimums such as Math.max(20, scaledRadius); use only small clamps that prevent invisibility.
- With SVG/viewBox geometry that already scales naturally, preserve that and avoid fixed px sizes that break it.
- If space is small, simplify or hide secondary labels instead of making marks oversized.

HOVER/CLICK (on user action only): hover → showTooltip(label,event)/hideTooltip(); cursor:pointer on interactive elements. Click → showPopup('Title','2–3 sentence explanation'). Animation: fill/opacity transitions only; no scale/translate/bounce.

CONTROLS (blueprint.interactions — render in UI section; add id="{id}Input" to every input). Each control's handler must teach the concept described in its "teaches" field:
  slider → <label>{label}: <output id="{id}Val">{default}</output><input id="{id}Input" type="range" min="{min}" max="{max}" step="{step}" value="{default}" oninput="document.getElementById('{id}Val').value=this.value;update_{id}(+this.value)"></label>  +  function update_{id}(v){}
  toggle → <label><input id="{id}Input" type="checkbox" onchange="toggle_{id}(this.checked)"> {label}</label>  +  function toggle_{id}(on){}
  button → <button onclick="trigger_{id}()">{label}</button>  +  function trigger_{id}(){}
  equation_input → one <label>{field.label} <input id="{field.id}Input" value="{field.default}"></label> per entry in the interaction's "fields"
  code_editor → a <textarea id="{id}Code"> plus sample tabs, an input for the interaction's "input", a Run button, and playback controls

DEMO STEPS (blueprint.demo_steps): if present and non-empty, build a step player in #ui:
  - A <p id="demoNarration" style="margin:0;font-size:10px;max-width:180px"> showing the current step's narration
  - <button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button>
  - Each step's .state sets matching interaction inputs to the specified values and calls their update functions
  - Step 0 is the default view (set on load); subsequent steps are one click away
  - Omit the player entirely if demo_steps is absent or empty

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: In the Hall-Héroult cell, dissolving Al2O3 in molten cryolite lets electrolysis run at manageable temperature: Al3+ is reduced to molten aluminum at the carbon cathode floor while O2- is oxidized at the carbon anodes, consuming them as bubbles of O2, CO, and CO2.
KEY INSIGHT (what students should walk away understanding): The cell splits the chemistry in space: Al3+ is reduced to liquid metal at the cathode floor while the carbon anodes are oxidized away as gas — so current controls production rate but also consumes the anodes.
DEMO STEPS: 3 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "In the Hall-Héroult cell, dissolving Al2O3 in molten cryolite lets electrolysis run at manageable temperature: Al3+ is reduced to molten aluminum at the carbon cathode floor while O2- is oxidized at the carbon anodes, consuming them as bubbles of O2, CO, and CO2.",
  "figureType": "diagram",
  "elements": [
    "outer steel shell (dark gray) enclosing the cell",
    "ceramic insulation lining (tan/peach) inside the shell",
    "two suspended carbon anodes (+), black blocks with rod connectors to a positive bus bar labeled '+'",
    "carbon cathode (−) forming the cell floor, connected to a negative terminal labeled '−'",
    "green electrolyte layer labeled 'Al2O3 dissolved in molten Na3AlF6'",
    "gray molten aluminum layer pooling above the cathode floor",
    "thin crust layer at the electrolyte surface, labeled 'Crust'",
    "white bubble dots around the anodes labeled 'Bubbles of O2, CO, and CO2'",
    "exhaust hood line at top labeled 'HF and particulates exhaust to filter plant' with upward arrow",
    "labels: 'Ceramic', 'Steel shell', 'Carbon anode (+)' on each anode, 'Carbon cathode (−)'"
  ],
  "interactions": [
    {
      "id": "cellRunning",
      "type": "animation",
      "label": "Run electrolysis",
      "loop": true,
      "teaches": "Electrolysis is a continuous transport process: Al3+ drifts to the cathode floor and plates out as molten aluminum while O2- is discharged at the anodes, where rising bubbles of O2, CO, and CO2 show the carbon anodes being consumed"
    },
    {
      "id": "currentSlider",
      "type": "slider",
      "label": "Applied current",
      "range": [
        0,
        100,
        5
      ],
      "default": 40,
      "teaches": "Higher current drives faster ion discharge — the bubble stream around the anodes intensifies and the molten aluminum layer above the cathode thickens more quickly, linking current to production rate"
    },
    {
      "id": "partLabels",
      "type": "hover",
      "teaches": "Hovering a component (anode, cathode, electrolyte, aluminum pool, crust, exhaust) reveals its role, keeping the busy cross-section uncluttered until the learner asks"
    }
  ],
  "demo_steps": [
    {
      "title": "Cell anatomy",
      "narration": "Explore the cross-section with hover: steel shell and ceramic lining contain the melt, carbon anodes hang into green cryolite electrolyte, and the carbon cathode is the entire floor.",
      "state": {
        "currentSlider": 0
      }
    },
    {
      "title": "Turn on the current",
      "narration": "Start the animation at low current: bubbles of O2, CO, and CO2 form around the anodes while molten aluminum slowly accumulates on the cathode floor — reduction happens at the bottom, oxidation at the anodes.",
      "state": {
        "currentSlider": 30
      }
    },
    {
      "title": "Crank up production",
      "narration": "Push the current slider high: bubbling intensifies and the aluminum layer visibly thickens faster — but the anodes are also being eaten away faster, which is why they must be replaced regularly.",
      "state": {
        "currentSlider": 90
      }
    }
  ],
  "keyInsight": "The cell splits the chemistry in space: Al3+ is reduced to liquid metal at the cathode floor while the carbon anodes are oxidized away as gas — so current controls production rate but also consumes the anodes.",
  "reconstructionNotes": "Vertical cross-section of a rectangular cell. Dark gray outer shell, peach ceramic liner just inside it. Green electrolyte fills most of the interior; a gray molten-aluminum pool sits at the bottom atop the black sloped cathode floor labeled 'Carbon cathode (−)'. Two black anode blocks hang from a top bus bar marked '+', each labeled 'Carbon anode (+)'. White dotted bubbles cluster around and beneath the anodes. A thin lighter crust band caps the electrolyte. Leader-line labels on the right: Crust, Bubbles of O2/CO/CO2, Al2O3 dissolved in molten Na3AlF6, Molten aluminum; on the left: Ceramic, Steel shell, '−' terminal. Top has an exhaust duct with upward arrow labeled 'HF and particulates exhaust to filter plant'. Animation: bubbles rise from anode undersides and pop at the crust; the gray aluminum layer grows upward at a rate tied to the slider; optional small + / − ion drift indicators (Al3+ downward, O2- toward anodes)."
}

systemPrompt:
You are a strict critic of generated inline-interactive 2D figures (SVG.js / Chart.js / Mermaid) against the original 2D textbook figure image.
You will receive the original source figure image, the generated HTML/JavaScript code, and a rendered screenshot of the generated HTML (if screenshot capture succeeds). Start by using the screenshot to help evaluate the faithfulness of the generated figure to the source figure, listing discrepancies in the primitive elements between what you see in the source figure versus what you see in the generated figure. If the screenshot was not received, mention this in the notes.
Score the generated figure using the rubric and give feedback to improve the figure. Be critical and honest — err toward lower scores when in doubt. The default (step-0) state should read as a drop-in replacement for the static source image. Do not give credit for things that are absent or barely present. Output ONLY a valid JSON object — no explanation, no markdown, no fences.

AUTOMATED VERIFICATION ALREADY PASSED. A deterministic verifier has rendered this figure headless at multiple viewports and confirmed it runs without exceptions or page errors, produces a visible visual root (SVG, canvas, or Mermaid diagram) containing real text or graphics rather than an empty frame, and fits the viewport with no horizontal overflow and the main visual unclipped at wide widths.
Spend NO scores, failure modes, discrepancies, or action items on any of that. Focus ENTIRELY on SEMANTIC FIDELITY to the source: correct 2D structure, correct mark types, faithful composition and colors, correct and meaningful labels, meaningful and conceptually-correct interactions, and concept accuracy. Judge whether it is the *right* figure and a good teaching artifact — not whether it renders.
IMPORTANT — the 2D verifier performs NO label checks at all: no on-screen check, no size check, no overlap check. Label placement is fully IN SCOPE for you. Do flag labels that collide with each other or the artwork, escape the plot area, are clipped at the edge, or are too small to read comfortably at inline size.

SCAFFOLD CONTEXT (provided automatically — do not penalise for missing these):
- SVG.js v3, Chart.js v4, Mermaid v11 and expr-eval are preloaded; #container, window.__markRendered() and the 'fig-resize' event are pre-wired
- #ui is an auto-docking control panel; setUiLayout(...) positions it
- showPopup(...), showTooltip(...), hideTooltip() — built-in explainer and tooltip affordances
- Plotting helpers: setPlotFrame(...), plotX(...) / plotY(...) for data→pixel mapping, plotFunction(...), fillBetween(...), plotParametric(...), integrateSimpson(...), findRoot(...)
- compileExpr(...) and bindEquationInput(...) — live user-editable equation inputs
- Generated code may add controls, panels, and UI affordances as needed to support the planned interactions

DISCREPANCIES - list 0-6 visual discrepancies between the source figure and the generated figure, prioritized by impact on recognizability and concept accuracy
- Focus on: wrong mark types, missing or incorrect elements, wrong colors, missing or mislabeled annotations, broken or absent interactions
- De-prioritize: exact crop/zoom, whitespace variation, small differences in font face or padding — only flag these if they make the figure hard to recognize or misleading
- For multipanel source figures, if the generated figure implements a toggle/tab/step between parts (e.g. Part A vs Part B), check the HTML/JS before flagging a part as "missing" — a part hidden behind an unactivated toggle is not a discrepancy

FAILURE MODES — list any that apply (use empty array [] if none):
"Missing-Labels"          — important text annotations are absent
"Wrong-Primitives"        — incorrect geometric shapes used for the concept
"Interaction-Broken"      — interactive controls are present but non-functional
"Interaction-Missing"     — no meaningful interactions beyond pan/zoom or hover tooltips
"Scale-Wrong"             — element proportions are noticeably off
"Color-Wrong"             — colors don't match the original figure
"Hallucination"           — elements present that do not appear in the original
"Concept-Misunderstood"   — the core concept being illustrated is    misrepresented

SCORES — integer 1–5 for each field:
geometry_accuracy — Judge 2D structural fidelity against the source: axis ranges, tick marks and gridlines, the shape and trend of the data, node-and-edge topology and counts, relative proportions and layout, and line styling (dashed vs solid, stroke weight, arrowheads, fill vs outline). Flag "Wrong-Primitives" and cap the score when a major element uses the wrong mark type — e.g. a scatter drawn as a connected line, a bar chart drawn as an area, a directed edge drawn without its arrowhead, a smooth curve drawn as straight segments. This is a 2D figure: do NOT penalise the absence of depth, perspective, or a 3D vantage point.
  5 – All elements represented; plausible positions, connections, proportions
  4 – All major elements present; minor position/alignment issues
  3 – 1-2 elements missing OR noticeable spatial errors; concept still recognizable
  2 – Multiple missing elements OR major spatial errors
  1 – Unrecognizable or completely wrong topology

interactivity_usability — CRITICAL: panning or zooming the figure does NOT count as an interaction, and a hover tooltip on its own is weak. Meaningful interactions = sliders, toggles, buttons, demo-step players, equation inputs, or code-editor workbenches built by the developer, whose handlers actually redraw the figure.
  5 – All planned interactions functional and pedagogically useful; count matches figure complexity (1 deep slider is correct for a single-variable concept; 3+ expected for multi-step figures); demo steps present if the plan includes them
  4 – Most planned interactions functional; minor usability issues; pedagogical value clear
  3 – At least one meaningful interaction works; some planned interactions missing or broken; or interactions only weakly connected to the concept
  2 – Interactions exist in code but broken or no visible effect
  1 – Only pan/zoom or a bare hover tooltip present, or no interactions at all — score MUST be 1

faithfulness — Judge overall visual resemblance to the source — composition, geometry, and color scheme at a glance — rather than an exhaustive checklist of small differences. For multipanel source figures where the generated figure implements a toggle/tab/step between parts (e.g. Part A vs Part B), it is correct and expected for only one part to be visible in the default screenshot; check the HTML/JS for a toggle control before penalizing a currently-hidden part as missing or absent. Do not over-penalize extra elements added beyond the source (additional UI chrome, decorative touches) unless they clutter the figure or change its overall look — flag those under the Hallucination failure mode rather than cutting this score for minor additions.
  5 – Clearly recognizable as the same figure: correct geometry, colors, composition, and major labels all present
  4 – Recognizable at a glance; minor differences in color, proportion, or label placement
  3 – General idea clear but notable differences in geometry, composition, or missing elements
  2 – Hard to recognize as the same figure; significant content differences
  1 – Completely different or fabricated

label_quality — Label placement is NOT screened by the verifier for 2D figures — judge it fully. Judge CONTENT (right labels present, correct text, on the correct element, matching the source), PLACEMENT (collisions with each other or the artwork, escaping the plot area, clipping at the edge), and LEGIBILITY (comfortably readable at inline size, with a deliberate hierarchy — primary labels standing out over axis labels — matching what the source implies).
  5 – All the right labels present, correct text on the correct elements, matching the source, cleanly placed without collisions, AND sized/styled for easy legibility with a clear hierarchy matching the source
  4 – Content correct; only 1-2 minor issues (content, placement, OR sizing/hierarchy — e.g. a label slightly too small, or one mild collision)
  3 – Half of labels have issues, whether content (wrong text, wrong target, missing, unclear), placement (overlapping, escaping the plot area, clipped), or legibility (uncomfortably small, inconsistent hierarchy)
  2 – Most labels problematic — mislabeled/missing content, badly colliding, or generally too small/cluttered to read comfortably
  1 – No labels, or all wrong/mislabeled/illegible

concept_accuracy:
  5 – All concepts accurate; interactions demonstrate correct relationships; no misinformation
  4 – Main concept correct; ≤1 minor detail wrong or missing
  3 – Main concept present; 2-3 details wrong or missing
  2 – Significant errors or fabrications; would mislead students
  1 – Completely incorrect or misleading

ACTION ITEMS — separate feedback for the generation and the plan:
- action_items: list 2-4 generation-level fixes (broken controls, wrong primitives, missing labels, scale issues, camera/view correction — things fixable without changing the plan)
- plan_action_items: list 0-2 plan-level fixes (wrong projection_type, missing core elements, wrong interaction type for the concept, fundamental misunderstanding — things requiring a revised plan). Use [] if the plan is sound.

Output this exact JSON structure and nothing else:
{
  "discrepancies": [],
  "failure_modes": [],
  "geometry_accuracy": 3,
  "interactivity_usability": 3,
  "faithfulness": 3,
  "label_quality": 3,
  "concept_accuracy": 3,
  "notes": "one concise sentence summarizing the main strengths and weaknesses",
  "action_items": [
    "Specific generation-level fix 1",
    "Specific generation-level fix 2"
  ],
  "plan_action_items": [
    "Specific plan-level fix 1 (or empty array if plan is sound)"
  ]
}

