tip(bath, 'Al₂O₃ dissolved in molten Na₃AlF₆', 'Electrolyte', 'Alumina dissolved in molten cryolite (~960 °C) — far below the 2072 °C needed to melt pure Al₂O₃. Ions move freely here: Al³⁺ drifts down to the cathode, O²⁻ toward the anodes.');

/* ── Crust ── */
var crust = draw.rect(444, 14).move(148, BATH_TOP - 8).fill('#d4dfa8');
tip(crust, 'Frozen crust', 'Crust', 'A frozen crust of bath and alumina caps the electrolyte, limiting heat loss and HF emissions.');

