var poolGrad = draw.gradient('linear', function (stop) {
  stop.at(0, '#c9c9c9');
  stop.at(0.5, '#9a9a9a');
  stop.at(1, '#6e6e6e');
}).from(0, 0).to(0, 1);
var POOL_BASE = 58; // default visible thickness
var pool = draw.rect(444, POOL_BASE).move(148, POOL_BOT - POOL_BASE).fill(poolGrad);
tip(pool, 'Molten aluminum', 'Molten aluminum', 'Pure liquid aluminum (denser than the bath) pools on the cathode floor and is tapped off periodically. Al³⁺ + 3e⁻ → Al(l).');

/* ── Cathode floor ── */
var cathode = draw.polygon('148,512 592,512 560,545 178,545').fill('#111');
tip(cathode, 'Carbon cathode (−)', 'Carbon cathode (−)', 'The carbon cell floor is the cathode: Al³⁺ ions are reduced here to liquid metal. The whole floor is one electrode.');

/* ── Anodes with multi-pronged yoke assemblies ── */
var anodeG = draw.group();
ANODE_X.forEach(function (ax) {
  var blk = anodeG.rect(ANODE_W, 160).move(ax - ANODE_W / 2, 250).fill('#0d0d0d').stroke({ color: '#000', width: 1 });
  // yoke: horizontal stub + three vertical prongs into the block
  anodeG.rect(96, 12).move(ax - 48, 196).fill('#3a3a3a').stroke({ color: '#222', width: 1 });
  [-34, 0, 34].forEach(function (off) {
    anodeG.rect(16, 58).move(ax + off - 8, 206).fill('#3a3a3a').stroke({ color: '#222', width: 1 });
  });
  anodeG.rect(22, 30).move(ax - 11, 168).fill('#3a3a3a'); // stem to bus bar
  tip(blk, 'Carbon anode (+)', 'Carbon anode (+)', 'O²⁻ is discharged at the anodes and reacts with the carbon: C + 2O²⁻ → CO₂ + 4e⁻. The anodes are literally burned away and must be replaced regularly.');
});

/* ── Bus bar (+) ── */
var bus = draw.group();
bus.line(180, 160, 620, 160).stroke({ color: '#333', width: 6 });
ANODE_X.forEach(function (ax) { bus.line(ax, 160, ax, 170).stroke({ color: '#333', width: 6 }); });
bus.text('+').font({ size: 26, family: 'sans-serif' }).move(630, 146);
tip(bus, 'Positive bus bar (+)', 'Positive terminal', 'Current enters through the + bus bar, travels down the anode rods, through the bath, and out through the cathode floor.');

/* ── Negative terminal ── */
var neg = draw.group();
neg.line(148, 528, 60, 528).stroke({ color: '#333', width: 6 });
neg.text('−').font({ size: 26, family: 'sans-serif' }).move(28, 512);

/* ── Exhaust hood (bold, two duct branches) ── */
