ex.polygon('340,28 330,48 350,48').fill('#333'); // arrowhead
ex.text('HF and particulates\nexhaust to filter plant').font({ size: 14, family: 'sans-serif' }).move(360, 62);
tip(ex, 'Exhaust to filter plant', 'Gas exhaust', 'Hot gases — including HF from the fluoride bath — are captured by the hood and scrubbed at the filter plant.');

/* ── Labels ── */
draw.text('Carbon\ncathode (−)').font({ size: 15, family: 'sans-serif', anchor: 'middle' }).fill('#fff').center(370, 528);
ANODE_X.forEach(function (ax) {
