});
leader(606, 293, 660, 293, 'Crust', 'right');
leader(575, 415, 660, 415, 'Bubbles of O₂, CO,', 'right');
draw.text('and CO₂').font({ size: 16, family: 'sans-serif' }).move(668, 430);
leader(600, 445, 660, 462, 'Al₂O₃ dissolved in', 'right');
draw.text('molten Na₃AlF₆').font({ size: 16, family: 'sans-serif' }).move(668, 477);
leader(600, 490, 660, 505, 'Molten aluminum', 'right');
leader(134, 380, 90, 380, 'Ceramic', 'left');
leader(122, 430, 90, 430, 'Steel shell', 'left');

/* ── Bubbles: static cluster always visible + animated stream ── */
var bubbleG = draw.group();
var bubbles = [];
// static cluster around both anodes (visible even at zero current)
ANODE_X.forEach(function (ax) {
  for (var i = 0; i < 26; i++) {
    var side = Math.random() < 0.5 ? -1 : 1;
    var x = ax + side * (ANODE_W / 2 + 4 + Math.random() * 16);
    var y = 330 + Math.random() * 95;
