    var c = bubbleG.circle(3 + Math.random() * 4).fill('#fff').stroke({ color: '#e6e6e6', width: 0.5 }).center(x, y);
    tip(c, 'O₂, CO, CO₂ bubble', 'Anode gas', 'Oxygen discharged at the carbon anode forms O₂, which reacts with the carbon to give CO and CO₂ — the bubbles mark the anode being consumed.');
  }
});
function spawnBubble() {
  var ax = ANODE_X[Math.random() < 0.5 ? 0 : 1];
  var x = ax + (Math.random() - 0.5) * (ANODE_W + 30);
  var c = bubbleG.circle(4 + Math.random() * 5).fill('#fff').stroke({ color: '#eee', width: 0.5 })
    .center(x, 405 + Math.random() * 55);
  bubbles.push({ el: c, vy: 0.4 + Math.random() * 0.8 });
  tip(c, 'O₂, CO, CO₂ bubble', 'Anode gas', 'Oxygen discharged at the carbon anode forms O₂, which reacts with the carbon to give CO and CO₂ — the bubbles mark the anode being consumed.');
}
var lastT = 0;
function tick(t) {
  var dt = Math.min(50, t - lastT); lastT = t;
  if (running && current > 0) {
    if (Math.random() < (current / 100) * 0.5 && bubbles.length < 90) spawnBubble();
    for (var i = bubbles.length - 1; i >= 0; i--) {
      var b = bubbles[i];
      b.el.cy(b.el.cy() - b.vy * dt * 0.06 * (0.5 + current / 60));
      if (b.el.cy() < BATH_TOP + 6) { b.el.remove(); bubbles.splice(i, 1); }
    }
    poolLevel += (current / 100) * dt * 0.00004;
    if (poolLevel > 1) poolLevel = 0;
  }
  var ph = poolLevel * POOL_MAX;
  pool.height(POOL_BASE + ph).y(POOL_BOT - POOL_BASE - ph);
  requestAnimationFrame(tick);
}
requestAnimationFrame(tick);

/* ── Interactions ── */
function update_currentSlider(v) {
  current = v;
  if (v > 0 && !running) trigger_cellRunning();
}
function trigger_cellRunning() {
  running = !running;
  var b = document.getElementById('runBtn');
  if (b) b.textContent = running ? '⏸ Pause electrolysis' : '▶ Run electrolysis';
}
function toggle_cellRunning(on) { if (on !== running) trigger_cellRunning(); }

/* ── Step player ── */
var steps = [
  { title: 'Cell anatomy', narration: 'Explore the cross-section with hover: steel shell and ceramic lining contain the melt, carbon anodes hang into green cryolite electrolyte, and the carbon cathode is the entire floor.', state: { currentSlider: 0 } },
  { title: 'Turn on the current', narration: 'Start the animation at low current: bubbles of O₂, CO, and CO₂ form around the anodes while molten aluminum slowly accumulates on the cathode floor — reduction happens at the bottom, oxidation at the anodes.', state: { currentSlider: 30 } },
  { title: 'Crank up production', narration: 'Push the current slider high: bubbling intensifies and the aluminum layer visibly thickens faster — but the anodes are also being eaten away faster, which is why they must be replaced regularly.', state: { currentSlider: 90 } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' of ' + steps.length;
  var v = s.state.currentSlider;
  var inp = document.getElementById('currentSliderInput');
  inp.value = v; document.getElementById('currentSliderVal').value = v;
  update_currentSlider(v);
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }
applyStep(0);
running = true;

window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: In the Hall-Héroult cell, dissolving Al2O3 in molten cryolite lets electrolysis run at manageable temperature: Al3+ is reduced to molten aluminum at the carbon cathode floor while O2- is oxidized at the carbon anodes, consuming them as bubbles of O2, CO, and CO2.
KEY INSIGHT (what students should walk away understanding): The cell splits the chemistry in space: Al3+ is reduced to liquid metal at the cathode floor while the carbon anodes are oxidized away as gas — so current controls production rate but also consumes the anodes.
DEMO STEPS: 3 guided steps — implement the step player in #ui

FULL BLUEPRINT:
