}

/* ── Steel shell (outer, dark gray) ── */
var shell = draw.rect(500, 262).move(120, 300).fill('#5a5a5a').stroke({ color: '#222', width: 2 });
tip(shell, 'Steel shell', 'Steel shell', 'The outer steel shell gives the cell structural strength and contains the high-temperature melt.');

/* ── Ceramic liner (peach) ── */
var ceramic = draw.rect(472, 234).move(134, 318).fill('#e8b39a').stroke({ color: '#a0705a', width: 1 });
tip(ceramic, 'Ceramic insulation', 'Ceramic lining', 'The ceramic lining insulates the cell thermally and protects the steel shell from the corrosive molten cryolite.');

/* ── Electrolyte (green cryolite bath) ── */
var bath = draw.rect(444, BATH_BOT - BATH_TOP).move(148, BATH_TOP).fill('#a8c45f');
tip(bath, 'Al₂O₃ dissolved in molten Na₃AlF₆', 'Electrolyte', 'Alumina dissolved in molten cryolite (~960 °C) — far below the 2072 °C needed to melt pure Al₂O₃. Ions move freely here: Al³⁺ drifts down to the cathode, O²⁻ toward the anodes.');

/* ── Crust (thin lighter band at surface) ── */
