});

/* ── Bus bar (+) spanning the top, + label at right end ── */
var bus = draw.group();
bus.line(160, 158, 650, 158).stroke({ color: '#333', width: 6 });
ANODE_X.forEach(function (ax) { bus.line(ax, 158, ax, 172).stroke({ color: '#333', width: 6 }); });
bus.text('+').font({ size: 28, family: 'sans-serif' }).move(660, 140);
tip(bus, 'Positive bus bar (+)', 'Positive terminal', 'Current enters through the + bus bar, travels down the anode rods, through the bath, and out through the cathode floor.');

/* ── Negative terminal (−) on the left ── */
