neg.line(148, 530, 60, 530).stroke({ color: '#333', width: 6 });
neg.text('−').font({ size: 28, family: 'sans-serif' }).move(28, 512);
tip(neg, 'Negative terminal (−)', 'Negative terminal', 'Current leaves the cell through the cathode floor and the − terminal.');

