  var v = s.state.currentSlider;
  var inp = document.getElementById('currentSliderInput');
  inp.value = v; document.getElementById('currentSliderVal').value = v;
  update_currentSlider(v);
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }
applyStep(0);
running = true;

window.__markRendered();
// @FIGURE_CODE_END

